ALTER TABLE public.plans ADD COLUMN IF NOT EXISTS verification_business_days integer NOT NULL DEFAULT 2;
ALTER TABLE public.plans ADD COLUMN IF NOT EXISTS verification_recheck_business_days integer NOT NULL DEFAULT 1;
ALTER TABLE public.plans ADD COLUMN IF NOT EXISTS verification_vat_pct numeric NOT NULL DEFAULT 7;
CREATE TABLE public.company_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL UNIQUE REFERENCES public.startups(id), status text NOT NULL DEFAULT 'not_ordered', included boolean NOT NULL DEFAULT false, order_id uuid, requested_by uuid, started_at timestamptz, ready_by timestamptz, checked_at timestamptz, affidavit_issued_on date, record_details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.company_verifications TO authenticated; GRANT ALL ON public.company_verifications TO service_role;
ALTER TABLE public.company_verifications ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.company_verification_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), verification_id uuid NOT NULL REFERENCES public.company_verifications(id), key integer NOT NULL, result text NOT NULL, values jsonb NOT NULL DEFAULT '{}', source_label text, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(verification_id,key));
GRANT SELECT ON public.company_verification_checks TO authenticated; GRANT ALL ON public.company_verification_checks TO service_role;
ALTER TABLE public.company_verification_checks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.verification_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.startups(id), ordered_by uuid NOT NULL, buyer_account_id uuid, amount numeric NOT NULL, vat numeric NOT NULL, total numeric NOT NULL, method text NOT NULL, slip text, status text NOT NULL DEFAULT 'pending', paid_at timestamptz, ref text NOT NULL UNIQUE DEFAULT ('PAY-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), receipt_no text, tax_invoice_no text, refund_requested_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.verification_orders TO authenticated; GRANT ALL ON public.verification_orders TO service_role;
ALTER TABLE public.verification_orders ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX verification_one_active_order ON public.verification_orders(company_id,ordered_by) WHERE status IN ('pending','paid');
CREATE TABLE public.verification_access (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES public.startups(id), buyer_account_id uuid NOT NULL, via text NOT NULL, opened_at timestamptz, open_until timestamptz, requested_at timestamptz, order_id uuid REFERENCES public.verification_orders(id), UNIQUE(company_id,buyer_account_id));
GRANT SELECT ON public.verification_access TO authenticated; GRANT ALL ON public.verification_access TO service_role;
ALTER TABLE public.verification_access ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.verification_usage (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), buyer_account_id uuid NOT NULL, company_id uuid NOT NULL REFERENCES public.startups(id), term_start timestamptz NOT NULL, consumed_at timestamptz NOT NULL DEFAULT now(), returned_at timestamptz, UNIQUE(buyer_account_id,company_id,term_start));
GRANT SELECT ON public.verification_usage TO authenticated; GRANT ALL ON public.verification_usage TO service_role;
ALTER TABLE public.verification_usage ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.verification_nda_valid(_uid uuid,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.deal_pipelines d WHERE d.buyer_user_id=_uid AND d.startup_id=_company AND d.nda_approved_at IS NOT NULL AND d.status NOT IN ('declined','withdrawn','revoked','ended') AND coalesce(d.nda_expires_at,d.nda_approved_at+interval '730 days')>now()); $$;
CREATE OR REPLACE FUNCTION public.verification_owner(_uid uuid,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_startup_member(_uid,_company) OR EXISTS(SELECT 1 FROM public.startup_ownership WHERE startup_id=_company AND owning_agent_user_id=_uid) OR (public.is_account_admin(_uid) AND public.can_access_startup(_uid,_company)); $$;
CREATE OR REPLACE FUNCTION public.verification_can_read(_uid uuid,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.verification_owner(_uid,_company) OR (public.verification_nda_valid(_uid,_company) AND EXISTS(SELECT 1 FROM public.verification_access a WHERE a.company_id=_company AND a.buyer_account_id=_uid AND (a.open_until IS NULL OR a.open_until>now()) AND ((a.via='paid' AND EXISTS(SELECT 1 FROM public.verification_orders o WHERE o.id=a.order_id AND o.ordered_by=_uid AND o.status='paid')) OR (a.via IN ('plan','contract') AND EXISTS(SELECT 1 FROM public.subscriptions s JOIN public.plans p ON p.id=s.plan_id JOIN public.plan_reports r ON r.plan_id=p.id AND r.report_key='verification' WHERE s.user_id=_uid AND s.status<>'ended' AND (s.term_end IS NULL OR s.term_end>now()) AND p.status='live' AND ((a.via='contract' AND r.mode='contract') OR (a.via='plan' AND r.mode='number' AND a.open_until IS NOT NULL AND a.open_until=s.term_end))))))); $$;
REVOKE ALL ON FUNCTION public.verification_nda_valid(uuid,uuid),public.verification_owner(uuid,uuid),public.verification_can_read(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.verification_nda_valid(uuid,uuid),public.verification_owner(uuid,uuid),public.verification_can_read(uuid,uuid) TO authenticated,service_role;
CREATE POLICY verification_private_read ON public.company_verifications FOR SELECT TO authenticated USING(public.verification_can_read(auth.uid(),company_id));
CREATE POLICY verification_checks_private_read ON public.company_verification_checks FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.company_verifications v WHERE v.id=verification_id AND public.verification_can_read(auth.uid(),v.company_id)));
CREATE POLICY verification_order_own ON public.verification_orders FOR SELECT TO authenticated USING(ordered_by=auth.uid() OR (public.is_account_admin(auth.uid()) AND public.can_access_startup(auth.uid(),company_id)));
CREATE POLICY verification_access_own ON public.verification_access FOR SELECT TO authenticated USING(buyer_account_id=auth.uid() AND public.verification_nda_valid(auth.uid(),company_id));
CREATE POLICY verification_usage_own ON public.verification_usage FOR SELECT TO authenticated USING(buyer_account_id=auth.uid());
CREATE OR REPLACE FUNCTION public.verification_business_due(_from timestamptz,_days integer) RETURNS timestamptz LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE d timestamp:=_from AT TIME ZONE 'Asia/Bangkok'; n integer:=0; BEGIN WHILE n<_days LOOP d:=d+interval '1 day'; IF extract(isodow FROM d)<6 THEN n:=n+1; END IF; END LOOP; RETURN d AT TIME ZONE 'Asia/Bangkok'; END; $$;
CREATE OR REPLACE FUNCTION public.verification_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_TABLE_NAME='company_verifications' AND NEW.status NOT IN ('not_ordered','waiting_payment','checking','certified','needs_fix') THEN RAISE EXCEPTION 'Invalid verification status'; ELSIF TG_TABLE_NAME='company_verification_checks' AND (NEW.key NOT BETWEEN 1 AND 6 OR NEW.result NOT IN ('match','mismatch')) THEN RAISE EXCEPTION 'Invalid verification check'; ELSIF TG_TABLE_NAME='verification_orders' AND (NEW.method NOT IN ('promptpay','card','transfer') OR NEW.status NOT IN ('pending','paid','refunded') OR NEW.amount<0 OR NEW.vat<0 OR NEW.total<>NEW.amount+NEW.vat OR (NEW.method='transfer' AND NEW.slip IS NULL)) THEN RAISE EXCEPTION 'Invalid verification order'; ELSIF TG_TABLE_NAME='verification_access' AND NEW.via NOT IN ('plan','paid','contract') THEN RAISE EXCEPTION 'Invalid verification access'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER verification_validate BEFORE INSERT OR UPDATE ON public.company_verifications FOR EACH ROW EXECUTE FUNCTION public.verification_validate();
CREATE TRIGGER verification_check_validate BEFORE INSERT OR UPDATE ON public.company_verification_checks FOR EACH ROW EXECUTE FUNCTION public.verification_validate();
CREATE TRIGGER verification_order_validate BEFORE INSERT OR UPDATE ON public.verification_orders FOR EACH ROW EXECUTE FUNCTION public.verification_validate();
CREATE TRIGGER verification_access_validate BEFORE INSERT OR UPDATE ON public.verification_access FOR EACH ROW EXECUTE FUNCTION public.verification_validate();
CREATE OR REPLACE FUNCTION public.verification_checks_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE vid uuid:=coalesce(NEW.verification_id,OLD.verification_id); cid uuid; n integer; bad integer; ts timestamptz:=now(); BEGIN SELECT count(*),count(*) FILTER(WHERE result='mismatch') INTO n,bad FROM public.company_verification_checks WHERE verification_id=vid; SELECT company_id INTO cid FROM public.company_verifications WHERE id=vid; IF n=6 THEN UPDATE public.company_verifications SET status=CASE WHEN bad=0 THEN 'certified' ELSE 'needs_fix' END,checked_at=ts WHERE id=vid; UPDATE public.startups SET registration_verified_at=CASE WHEN bad=0 THEN ts ELSE NULL END WHERE id=cid; IF EXISTS(SELECT 1 FROM public.company_verification_checks WHERE verification_id=vid AND key=1 AND result='mismatch') THEN UPDATE public.verification_usage SET returned_at=ts WHERE company_id=cid AND returned_at IS NULL; UPDATE public.verification_orders SET refund_requested_at=ts WHERE company_id=cid AND status='paid'; END IF; ELSE UPDATE public.company_verifications SET status='checking',checked_at=NULL WHERE id=vid; UPDATE public.startups SET registration_verified_at=NULL WHERE id=cid; END IF; RETURN coalesce(NEW,OLD); END; $$;
REVOKE ALL ON FUNCTION public.verification_checks_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER verification_checks_changed AFTER INSERT OR UPDATE OR DELETE ON public.company_verification_checks FOR EACH ROW EXECUTE FUNCTION public.verification_checks_changed();
CREATE OR REPLACE FUNCTION public.verification_start_included(_company uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days integer; BEGIN IF NOT EXISTS(SELECT 1 FROM public.startups WHERE id=_company AND nullif(trim(registered_number),'') IS NOT NULL) THEN RETURN; END IF; SELECT p.verification_business_days INTO days FROM public.subscriptions s JOIN public.plans p ON p.id=s.plan_id WHERE s.status<>'ended' AND (s.term_end IS NULL OR s.term_end>now()) AND p.status='live' AND p.verification_mode='included' AND (EXISTS(SELECT 1 FROM public.startup_users u WHERE u.startup_id=_company AND u.user_id=s.user_id) OR EXISTS(SELECT 1 FROM public.startup_ownership o WHERE o.startup_id=_company AND o.owning_agent_user_id=s.user_id)) LIMIT 1; IF days IS NOT NULL THEN INSERT INTO public.company_verifications(company_id,status,included,started_at,ready_by) VALUES(_company,'checking',true,now(),public.verification_business_due(now(),days)) ON CONFLICT(company_id) DO UPDATE SET status='checking',included=true,started_at=now(),ready_by=public.verification_business_due(now(),days) WHERE company_verifications.status='not_ordered'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.verification_start_included(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.verification_start_included(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.verification_profile_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE days integer; BEGIN PERFORM public.verification_start_included(NEW.id); IF TG_OP='UPDATE' AND (NEW.registered_name IS DISTINCT FROM OLD.registered_name OR NEW.registered_number IS DISTINCT FROM OLD.registered_number) THEN SELECT verification_recheck_business_days INTO days FROM public.plans WHERE status='live' AND role='seller' ORDER BY sort LIMIT 1; UPDATE public.company_verifications SET status='checking',started_at=now(),ready_by=public.verification_business_due(now(),coalesce(days,1)),checked_at=NULL WHERE company_id=NEW.id AND status IN ('needs_fix','certified'); IF FOUND THEN UPDATE public.startups SET registration_verified_at=NULL WHERE id=NEW.id AND registration_verified_at IS NOT NULL; END IF; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.verification_profile_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zzzz_verification_profile_changed AFTER INSERT OR UPDATE OF registered_number,registered_name ON public.startups FOR EACH ROW EXECUTE FUNCTION public.verification_profile_changed();
CREATE OR REPLACE FUNCTION public.verification_open(_uid uuid,_company uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.subscriptions; p public.plans; r public.plan_reports; a public.verification_access; v public.company_verifications; used integer; until_date timestamptz; BEGIN IF NOT public.verification_nda_valid(_uid,_company) THEN RAISE EXCEPTION 'Your NDA is no longer active'; END IF; SELECT * INTO s FROM public.subscriptions WHERE user_id=_uid FOR UPDATE; IF NOT FOUND OR s.status='ended' OR (s.term_end IS NOT NULL AND s.term_end<=now()) THEN RAISE EXCEPTION 'Choose an active plan'; END IF; SELECT * INTO p FROM public.plans WHERE id=s.plan_id AND status='live' AND role='buyer'; SELECT * INTO r FROM public.plan_reports WHERE plan_id=p.id AND report_key='verification'; SELECT * INTO a FROM public.verification_access WHERE buyer_account_id=_uid AND company_id=_company; IF a.id IS NOT NULL AND public.verification_can_read(_uid,_company) THEN RETURN jsonb_build_object('reopened',true); END IF; IF r.mode='number' THEN IF s.term_end IS NULL THEN RAISE EXCEPTION 'Your plan needs an end date'; END IF; SELECT count(*) INTO used FROM public.verification_usage WHERE buyer_account_id=_uid AND term_start=s.term_start AND returned_at IS NULL; IF used>=coalesce(r.per_term,0) THEN RAISE EXCEPTION 'No company verification reports left'; END IF; INSERT INTO public.verification_usage(buyer_account_id,company_id,term_start) VALUES(_uid,_company,s.term_start) ON CONFLICT(buyer_account_id,company_id,term_start) DO UPDATE SET returned_at=NULL,consumed_at=now(); until_date:=s.term_end; ELSIF r.mode='contract' THEN until_date:=NULL; ELSE RAISE EXCEPTION 'This report is not included in your plan'; END IF; SELECT * INTO v FROM public.company_verifications WHERE company_id=_company FOR UPDATE; IF v.id IS NULL OR v.status IN ('not_ordered','waiting_payment') THEN INSERT INTO public.company_verifications(company_id,status,requested_by,started_at,ready_by) VALUES(_company,'checking',_uid,now(),public.verification_business_due(now(),p.verification_business_days)) ON CONFLICT(company_id) DO UPDATE SET status='checking',requested_by=_uid,started_at=now(),ready_by=public.verification_business_due(now(),p.verification_business_days); END IF; INSERT INTO public.verification_access(company_id,buyer_account_id,via,opened_at,requested_at,open_until) VALUES(_company,_uid,CASE WHEN r.mode='contract' THEN 'contract' ELSE 'plan' END,now(),CASE WHEN v.status IS DISTINCT FROM 'certified' THEN now() END,until_date) ON CONFLICT(company_id,buyer_account_id) DO UPDATE SET via=excluded.via,opened_at=excluded.opened_at,requested_at=excluded.requested_at,open_until=excluded.open_until,order_id=NULL; RETURN jsonb_build_object('reopened',false); END; $$;
REVOKE ALL ON FUNCTION public.verification_open(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.verification_open(uuid,uuid) TO service_role;
COMMENT ON TABLE public.company_verifications IS 'Private official company checks; certified state alone is projected publicly. Shareholders are never part of report DTOs.';
COMMENT ON COLUMN public.verification_orders.refund_requested_at IS 'Refund due when register has no company; provider confirmation must precede refunded status.';